UPDATE email_templates SET subject = 'Verify your email address — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Verify Email</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;-webkit-font-smoothing:antialiased;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;letter-spacing:-0.3px;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Verify your email address</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Thank you for signing up for <strong>{brand}</strong>! Please verify your email address to activate your account and get started.</p><p style="margin:0 0 4px;color:#94a3b8;font-size:13px;">This link will expire in <strong>{expiry_time}</strong>.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Verify Email Address</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, Thank you for signing up for {brand}! Verify your email: {action_url} This link expires in {expiry_time}.' WHERE slug = 'email_verify' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'تایید آدرس ایمیل — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>تایید ایمیل</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;-webkit-font-smoothing:antialiased;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">تایید آدرس ایمیل شما</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">از ثبت‌نام شما در <strong>{brand}</strong> سپاسگزاریم! لطفاً آدرس ایمیل خود را تایید کنید تا حساب‌تان فعال شود.</p><p style="margin:0 0 4px;color:#94a3b8;font-size:13px;">این لینک تا <strong>{expiry_time}</strong> معتبر است.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">تایید ایمیل</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، برای تایید ایمیل روی لینک زیر کلیک کنید: {action_url} این لینک تا {expiry_time} معتبر است.' WHERE slug = 'email_verify' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'E-posta adresinizi doğrulayın — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>E-posta Doğrulama</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;-webkit-font-smoothing:antialiased;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">E-posta adresinizi doğrulayın</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{brand}</strong> kaydolduğunuz için teşekkürler! Hesabınızı aktifleştirmek için e-posta adresinizi doğrulayın.</p><p style="margin:0 0 4px;color:#94a3b8;font-size:13px;">Bu bağlantının süresi <strong>{expiry_time}</strong> içinde dolacaktır.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">E-postayı Doğrula</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {brand} e-postanızı doğrulayın: {action_url} Süresi: {expiry_time}.' WHERE slug = 'email_verify' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Reset your password — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Password Reset</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;-webkit-font-smoothing:antialiased;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Reset your password</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">We received a request to reset the password for your <strong>{brand}</strong> account. Click the button below to choose a new password.</p><p style="margin:0 0 4px;color:#94a3b8;font-size:13px;">This link will expire in <strong>{expiry_time}</strong>. If you did not request this, you can safely ignore this email.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Reset Password</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, Reset your {brand} password: {action_url} Expires in {expiry_time}.' WHERE slug = 'password_reset' AND locale = 'en' AND workspace_id IS NULL;

