></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، برای بازنشانی رمز عبور: {action_url} تا {expiry_time} معتبر است.' WHERE slug = 'password_reset' AND locale = 'fa' AND workspace_id IS NULL;

