</td></tr></table></body></html>', text_body = 'Merhaba {name}, {brand} şifrenizi sıfırlayın: {action_url} Süresi: {expiry_time}.' WHERE slug = 'password_reset' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Welcome to {brand}! 🎉', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Welcome</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Welcome aboard! 🎉</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Your <strong>{brand}</strong> account is ready! We are excited to have you on board.</p><ul style="margin:0 0 16px;padding-left:20px;color:#475569;font-size:15px;line-height:28px;"><li>Set up your workspace</li><li>Invite your team members</li><li>Explore features and integrations</li></ul></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Get Started</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, Welcome to {brand}! Your account is ready. Get started: {action_url}' WHERE slug = 'welcome' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'به {brand} خوش آمدید! 🎉', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>خوش آمدید</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">خوش آمدید! 🎉</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">حساب <strong>{brand}</strong> شما آماده است! خوشحالیم که به ما پیوستید.</p><ul style="margin:0 0 16px;padding-right:20px;color:#475569;font-size:15px;line-height:28px;"><li>راه‌اندازی فضای کار</li><li>دعوت از اعضای تیم</li><li>بررسی امکانات</li></ul></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">شروع کنید</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، به {brand} خوش آمدید! شروع: {action_url}' WHERE slug = 'welcome' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = '{brand} hoş geldiniz! 🎉', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Hoş Geldiniz</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Hoş geldiniz! 🎉</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{brand}</strong> hesabınız hazır!</p><ul style="margin:0 0 16px;padding-left:20px;color:#475569;font-size:15px;line-height:28px;"><li>Çalışma alanınızı kurun</li><li>Ekip üyelerinizi davet edin</li><li>Özellikleri keşfedin</li></ul></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Başlayın</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {brand} hoş geldiniz! Başlayın: {action_url}' WHERE slug = 'welcome' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Your login link — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Magic Link</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Your login link</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Click the button below to securely log in to your <strong>{brand}</strong> account. No password needed.</p><p style="margin:0 0 4px;color:#94a3b8;font-size:13px;">This link will expire in <strong>{expiry_time}</strong> and can only be used once.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Log In</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, Log in to {brand}: {action_url} Expires in {expiry_time}.' WHERE slug = 'magic_link' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'لینک ورود شما — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>لینک ورود</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">لینک ورود شما</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">روی دکمه زیر کلیک کنید تا وارد حساب <strong>{brand}</strong> خود شوید.</p><p style="margin:0 0 4px;color:#94a3b8;font-size:13px;">این لینک تا <strong>{expiry_time}</strong> معتبر است و فقط یکبار قابل استفاده است.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">ورود به حساب</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، ورود به {brand}: {action_url} تا {expiry_time} معتبر است.' WHERE slug = 'magic_link' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Giriş bağlantınız — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Giriş Bağlantısı</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Giriş bağlantınız</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{brand}</strong> hesabınıza güvenli giriş için aşağıdaki düğmeye tıklayın.</p><p style="margin:0 0 4px;color:#94a3b8;font-size:13px;">Bu bağlantının süresi <strong>{expiry_time}</strong> içinde dolacaktır.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Giriş Yap</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {brand} girişi: {action_url} Süresi: {expiry_time}.' WHERE slug = 'magic_link' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'You have been invited to {workspace} — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Team Invite</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">You are invited!</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{inviter}</strong> has invited you to join <strong>{workspace}</strong> on {brand} as a <strong>{role}</strong>.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Accept Invitation</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, {inviter} invited you to {workspace} on {brand} as {role}. Accept: {action_url}' WHERE slug = 'invite_member' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'دعوت به {workspace} — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>دعوت به تیم</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">شما دعوت شده‌اید!</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{inviter}</strong> شما را به <strong>{workspace}</strong> در {brand} با نقش <strong>{role}</strong> دعوت کرده است.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">پذیرش دعوت</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، {inviter} شما را به {workspace} دعوت کرده. پذیرش: {action_url}' WHERE slug = 'invite_member' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = '{workspace} davet edildiniz — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Takım Daveti</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Davet edildiniz!</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{inviter}</strong> sizi {brand} uzerinde <strong>{workspace}</strong> olarak <strong>{role}</strong> davet etti.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Daveti Kabul Et</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {inviter} sizi {workspace} davet etti. Kabul: {action_url}' WHERE slug = 'invite_member' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Payment received — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Payment Received</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Payment confirmed ✅</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Your payment of <strong>{amount} {currency}</strong> for the <strong>{plan}</strong> plan has been successfully processed.</p><table role="presentation" style="width:100%;border:1px solid #e2e8f0;border-radius:8px;margin:16px 0;"><tr><td style="padding:12px 16px;border-bottom:1px solid #e2e8f0;color:#94a3b8;font-size:13px;">Amount</td><td style="padding:12px 16px;border-bottom:1px solid #e2e8f0;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{amount} {currency}</td></tr><tr><td style="padding:12px 16px;color:#94a3b8;font-size:13px;">Plan</td><td style="padding:12px 16px;color:#1e293b;font-size:14px;font-weight:600;text-align:right;">{plan}</td></tr></table></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{invoice_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">View Invoice</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, Payment of {amount} {currency} for {plan} confirmed. Invoice: {invoice_url}' WHERE slug = 'payment_success' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'پرداخت موفق — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>پرداخت موفق</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">پرداخت تایید شد ✅</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">پرداخت شما به مبلغ <strong>{amount} {currency}</strong> برای پلن <strong>{plan}</strong> با موفقیت انجام شد.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{invoice_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">مشاهده فاکتور</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، پرداخت {amount} {currency} برای پلن {plan} تایید شد.' WHERE slug = 'payment_success' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Ödeme alındı — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Ödeme Alındı</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Ödeme onaylandı ✅</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{plan}</strong> planı için <strong>{amount} {currency}</strong> ödeme işlendi.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{invoice_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Faturayı Görüntüle</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {plan} planı için {amount} {currency} ödeme onaylandı.' WHERE slug = 'payment_success' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Payment failed — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Payment Failed</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Payment failed ⚠️</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">We were unable to process your payment of <strong>{amount} {currency}</strong>.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>Reason:</strong> {reason}</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Please update your payment method to avoid service interruption.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Update Payment Method</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, Payment of {amount} {currency} failed. Reason: {reason} Update: {action_url}' WHERE slug = 'payment_failed' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'پرداخت ناموفق — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>پرداخت ناموفق</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">پرداخت ناموفق ⚠️</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">پرداخت شما به مبلغ <strong>{amount} {currency}</strong> انجام نشد.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>دلیل:</strong> {reason}</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">بروزرسانی روش پرداخت</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، پرداخت {amount} {currency} ناموفق بود. دلیل: {reason}' WHERE slug = 'payment_failed' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Ödeme başarısız — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Ödeme Başarısız</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Ödeme başarısız ⚠️</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{amount} {currency}</strong> ödemeniz işlenemedi.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>Sebep:</strong> {reason}</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Ödeme Yöntemini Güncelle</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {amount} {currency} ödeme başarısız. Sebep: {reason}' WHERE slug = 'payment_failed' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'New conversation from {visitor} — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>New Conversation</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">New conversation 💬</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">A new conversation has been started by <strong>{visitor}</strong>:</p><div style="background:#f8fafc;border-left:4px solid #3B82F6;padding:16px;border-radius:0 8px 8px 0;margin:16px 0;"><p style="margin:0;color:#334155;font-size:14px;line-height:22px;font-style:italic;">{message}</p></div></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Reply Now</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, New message from {visitor}: "{message}" Reply: {action_url}' WHERE slug = 'new_conversation' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'گفتگوی جدید از {visitor} — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>گفتگوی جدید</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">گفتگوی جدید 💬</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">یک گفتگوی جدید توسط <strong>{visitor}</strong> شروع شده:</p><div style="background:#f8fafc;border-right:4px solid #3B82F6;padding:16px;border-radius:8px 0 0 8px;margin:16px 0;"><p style="margin:0;color:#334155;font-size:14px;line-height:22px;font-style:italic;">{message}</p></div></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">پاسخ دهید</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، پیام جدید از {visitor}: "{message}" پاسخ: {action_url}' WHERE slug = 'new_conversation' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = '{visitor} yeni görüşme — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Yeni Görüşme</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Yeni görüşme 💬</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{visitor}</strong> yeni bir görüşme başlattı:</p><div style="background:#f8fafc;border-left:4px solid #3B82F6;padding:16px;border-radius:0 8px 8px 0;margin:16px 0;"><p style="margin:0;color:#334155;font-size:14px;line-height:22px;font-style:italic;">{message}</p></div></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Yanıtla</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {visitor} yeni mesaj: "{message}" Yanıtla: {action_url}' WHERE slug = 'new_conversation' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Subscription renewed — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Subscription Renewed</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Subscription renewed 🔄</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Your <strong>{plan}</strong> subscription has been renewed for <strong>{amount}</strong>. Next renewal: <strong>{next_date}</strong>.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, Your {plan} subscription renewed for {amount}. Next: {next_date}.' WHERE slug = 'subscription_renewed' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'تمدید اشتراک — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>تمدید اشتراک</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">اشتراک تمدید شد 🔄</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">اشتراک <strong>{plan}</strong> شما به مبلغ <strong>{amount}</strong> تمدید شد. تمدید بعدی: <strong>{next_date}</strong>.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، اشتراک {plan} تمدید شد. مبلغ: {amount}. بعدی: {next_date}.' WHERE slug = 'subscription_renewed' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Abonelik yenilendi — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Abonelik Yenilendi</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Abonelik yenilendi 🔄</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{plan}</strong> aboneliğiniz <strong>{amount}</strong> karşılığında yenilendi. Sonraki: <strong>{next_date}</strong>.</p></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {plan} aboneliği {amount} yenilendi. Sonraki: {next_date}.' WHERE slug = 'subscription_renewed' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Subscription cancelled — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Subscription Cancelled</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Subscription cancelled</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Your <strong>{plan}</strong> subscription has been cancelled. You will continue to have access until <strong>{end_date}</strong>.</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">We would love to have you back! You can resubscribe at any time.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Resubscribe</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, Your {plan} subscription cancelled. Access until {end_date}.' WHERE slug = 'subscription_cancelled' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'لغو اشتراک — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>لغو اشتراک</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">اشتراک لغو شد</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">اشتراک <strong>{plan}</strong> شما لغو شد. دسترسی شما تا <strong>{end_date}</strong> ادامه دارد.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">اشتراک مجدد</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، اشتراک {plan} لغو شد. دسترسی تا {end_date}.' WHERE slug = 'subscription_cancelled' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Abonelik iptal edildi — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Abonelik İptal</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Abonelik iptal edildi</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{plan}</strong> aboneliğiniz iptal edildi. <strong>{end_date}</strong> tarihine kadar erişiminiz devam edecek.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Tekrar Abone Ol</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {plan} aboneliği iptal edildi. Erişim: {end_date}.' WHERE slug = 'subscription_cancelled' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Task assigned: {task} — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Task Assigned</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">New task assigned 📋</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{assigner}</strong> assigned you a new task:</p><div style="background:#f8fafc;border-left:4px solid #3B82F6;padding:16px;border-radius:0 8px 8px 0;margin:16px 0;"><p style="margin:0;color:#1e293b;font-size:15px;font-weight:600;">{task}</p></div></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">View Task</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, {assigner} assigned you: {task} View: {action_url}' WHERE slug = 'task_assigned' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'وظیفه جدید: {task} — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>وظیفه جدید</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">وظیفه جدید 📋</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{assigner}</strong> یک وظیفه جدید به شما اختصاص داده:</p><div style="background:#f8fafc;border-right:4px solid #3B82F6;padding:16px;border-radius:8px 0 0 8px;margin:16px 0;"><p style="margin:0;color:#1e293b;font-size:15px;font-weight:600;">{task}</p></div></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">مشاهده وظیفه</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، {assigner} وظیفه‌ای به شما داد: {task} مشاهده: {action_url}' WHERE slug = 'task_assigned' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Görev atandı: {task} — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Görev Atandı</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Yeni görev 📋</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{assigner}</strong> size yeni bir görev atadı:</p><div style="background:#f8fafc;border-left:4px solid #3B82F6;padding:16px;border-radius:0 8px 8px 0;margin:16px 0;"><p style="margin:0;color:#1e293b;font-size:15px;font-weight:600;">{task}</p></div></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Görevi Görüntüle</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {assigner} size görev atadı: {task} Görüntüle: {action_url}' WHERE slug = 'task_assigned' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Your account expires in {days_left} days — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Account Expiry</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Account expiring soon ⏰</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Hi {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Your <strong>{plan}</strong> plan on <strong>{brand}</strong> expires in <strong>{days_left} days</strong>. Renew now to keep your data and access.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Renew Now</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = 'Hi {name}, Your {plan} plan expires in {days_left} days. Renew: {action_url}' WHERE slug = 'account_expiry' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'حساب شما تا {days_left} روز دیگر منقضی می‌شود — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>انقضای حساب</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">حساب در حال انقضا ⏰</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">سلام {name}،</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">پلن <strong>{plan}</strong> شما در <strong>{brand}</strong> تا <strong>{days_left} روز</strong> دیگر منقضی می‌شود.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">تمدید</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'سلام {name}، پلن {plan} شما تا {days_left} روز دیگر منقضی می‌شود. تمدید: {action_url}' WHERE slug = 'account_expiry' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = 'Hesabınız {days_left} gün içinde sona eriyor — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Hesap Süresi</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Hesap süresi doluyor ⏰</h2><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;">Merhaba {name},</p><p style="margin:0 0 12px;color:#475569;font-size:15px;line-height:24px;"><strong>{brand}</strong> uzerindeki <strong>{plan}</strong> planınız <strong>{days_left} gün</strong> icinde sona eriyor.</p></td></tr><tr><td align="center" style="padding:30px 0;"><a href="{action_url}" style="display:inline-block;background-color:#3B82F6;color:#ffffff;font-size:16px;font-weight:600;text-decoration:none;padding:14px 32px;border-radius:8px;">Şimdi Yenile</a></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = 'Merhaba {name}, {plan} planınız {days_left} gün icinde sona eriyor. Yenile: {action_url}' WHERE slug = 'account_expiry' AND locale = 'tr' AND workspace_id IS NULL;

UPDATE email_templates SET subject = '[{severity}] {title} — {brand}', html_body = '<!DOCTYPE html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>System Alert</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">System Alert 🔔</h2><div style="background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:16px;margin:0 0 16px;"><p style="margin:0 0 4px;color:#991b1b;font-size:13px;font-weight:600;text-transform:uppercase;">{severity}</p><p style="margin:0 0 8px;color:#1e293b;font-size:16px;font-weight:600;">{title}</p><p style="margin:0;color:#475569;font-size:14px;line-height:22px;">{message}</p></div></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}. All rights reserved.</p></td></tr></table></td></tr></table></body></html>', text_body = '[{severity}] {title} — {message}' WHERE slug = 'system_alert' AND locale = 'en' AND workspace_id IS NULL;

UPDATE email_templates SET subject = '[{severity}] {title} — {brand}', html_body = '<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>هشدار سیستم</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:right;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">هشدار سیستم 🔔</h2><div style="background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:16px;margin:0 0 16px;"><p style="margin:0 0 4px;color:#991b1b;font-size:13px;font-weight:600;">{severity}</p><p style="margin:0 0 8px;color:#1e293b;font-size:16px;font-weight:600;">{title}</p><p style="margin:0;color:#475569;font-size:14px;line-height:22px;">{message}</p></div></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = '[{severity}] {title} — {message}' WHERE slug = 'system_alert' AND locale = 'fa' AND workspace_id IS NULL;

UPDATE email_templates SET subject = '[{severity}] {title} — {brand}', html_body = '<!DOCTYPE html><html lang="tr" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Sistem Uyarısı</title></head><body style="margin:0;padding:0;background-color:#f4f5f7;font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica Neue,Arial,sans-serif;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background-color:#f4f5f7;"><tr><td align="center" style="padding:40px 20px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:560px;background-color:#ffffff;border-radius:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);overflow:hidden;"><tr><td style="background:linear-gradient(135deg,#3B82F6,#1E40AF);padding:32px 40px;text-align:center;"><h1 style="margin:0;color:#ffffff;font-size:22px;font-weight:700;">{brand}</h1></td></tr><tr><td style="padding:40px;text-align:left;"><h2 style="margin:0 0 16px;color:#1e293b;font-size:20px;font-weight:600;">Sistem Uyarısı 🔔</h2><div style="background:#fef2f2;border:1px solid #fecaca;border-radius:8px;padding:16px;margin:0 0 16px;"><p style="margin:0 0 4px;color:#991b1b;font-size:13px;font-weight:600;text-transform:uppercase;">{severity}</p><p style="margin:0 0 8px;color:#1e293b;font-size:16px;font-weight:600;">{title}</p><p style="margin:0;color:#475569;font-size:14px;line-height:22px;">{message}</p></div></td></tr><tr><td style="padding:24px 40px;background-color:#f8fafc;border-top:1px solid #e2e8f0;text-align:center;"><p style="margin:0;color:#94a3b8;font-size:12px;line-height:20px;">&copy; {year} {brand}</p></td></tr></table></td></tr></table></body></html>', text_body = '[{severity}] {title} — {message}' WHERE slug = 'system_alert' AND locale = 'tr' AND workspace_id IS NULL;